def build(c):
 stages=[];states=[];parts=dict(dropdown=False,brand=False,photo=False,controls=False,catalog=False,editorial=False,form=False,filters=False,calc=False,faq=False,contact=False,credits=False)
 files=dict(html='',css=BASE,js='// დაწერე ქცევა შესაბამის ეტაპზე.');blank=dict(html='<!-- შენი ZIP-ის დიზაინის აწყობა აქ იწყება. -->',css=BASE,js=files['js'])
 def render():
  body=hero(c,parts['photo'],parts['controls'])
  if c['id']=='health' and parts['editorial']:body+=editorial(c)
  if parts['catalog']:body+=catalog(c,parts['filters'])
  if c['id']=='branon' and parts['editorial']:body+=editorial(c)
  if parts['editorial']:body+=news(c)
  if parts['form']:body+=form(c)
  if parts['calc']:body=body.replace('<div id="estimate-slot"></div>',calc(c))
  if parts['faq']:body+=faq(c)
  credits='<section id="credits" class="container credits"><p>'+c['original']+'</p><p>გაკვეთილები და კოდის სასწავლო ვერსია: Firstlight. ორიგინალის ვიზუალურ მასალებს ახალი ავტორობა არ მიეწერება.</p></section>' if parts['credits'] else ''
  files['html']=header(c,parts['dropdown'],parts['brand'])+'<main>'+body+'</main>'+footer(c,parts['contact'])+credits
