def delta(before,after):
 start=0
 while start<min(len(before),len(after)) and before[start]==after[start]:start+=1
 end=0
 while end<min(len(before)-start,len(after)-start) and before[-end-1]==after[-end-1]:end+=1
 removed=before[start:len(before)-end if end else len(before)]
 return dict(at=len(before[:start].encode('utf-16-le'))//2,remove=len(removed.encode('utf-16-le'))//2,insert=after[start:len(after)-end if end else len(after)])
